using SteamEngine.Common;

namespace SteamEngine.CompiledScripts {

	/// <summary>#962 - a skill's live DELAY, EFFECT and ADVRATE on Erebor, generated by the converter into systems/skillvalues.def.
	/// Those beat what the [SkillDef] sections say.</summary>
	public class SkillValuesDef : AbstractDef {
		private string skill, delay, effect, advRate;

		public SkillValuesDef(string defname, string filename, int headerLine)
			: base(defname, filename, headerLine) {
		}

		public override void LoadScriptLines(PropsSection ps) {
			foreach (PropsLine prop in ps.PropsLines) {
				switch (prop.Name.ToLowerInvariant()) {
					case "skill":
						this.skill = prop.Value;
						break;
					case "delay":
						this.delay = prop.Value;
						break;
					case "effect":
						this.effect = prop.Value;
						break;
					case "advrate":
						this.advRate = prop.Value;
						break;
				}
			}
		}

		protected override void On_AfterLoadFromScripts() {
			base.On_AfterLoadFromScripts();
			SkillDef def = SkillDef.GetByDefname(this.skill) as SkillDef;
			if (def == null) {
				Logger.WriteWarning(this.Filename, this.HeaderLine, "Values for " + this.skill + ", which doesn't exist.");
			} else {
				def.SetLiveValues(this.Filename, this.HeaderLine, this.delay, this.effect, this.advRate);
			}
		}
	}
}
